  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 What Statistics Is and Types of Data$j$, $j${"readings": [{"title": "Numbers 1 (King James Version)", "url": "/portal/bible/Numbers/1"}], "body": "Statistics is the science of collecting, organizing, analyzing and interpreting data so that we can make wise decisions. Data are facts and numbers gathered to answer a question. The Bible records some of the earliest counting of a people. In Numbers 1:2 the LORD told Moses, Take ye the sum of all the congregation of the children of Israel, after their families, by the house of their fathers, with the number of their names. A count like this is a form of data collection, and leaders still count attendance, giving and needs today so that they can serve well.\n\nEvery study begins with a question and a group to study. The population is the entire group we want to know about, such as every student in a school. A sample is a smaller part of the population that we actually measure. A parameter is a number that describes a population, and a statistic is a number that describes a sample. Each person or thing we measure is an individual, and each characteristic we record about it is a variable.\n\nVariables come in two main types. A categorical variable places individuals into groups or categories, such as favorite hymn, grade level or eye color. A quantitative variable is a number that can be counted or measured, such as height, age or the number of songs a choir sings. Quantitative variables are discrete when they are counted in whole numbers, such as the number of siblings, and continuous when they can take any value in an interval, such as height or time. Not every number is quantitative. A zip code or a jersey number is only a label, so it is categorical.\n\nExample: a pastor surveys 50 members of a church of 400 and records each person's age, favorite service day and number of children. The population is the 400 members and the sample is the 50. Age is continuous, the number of children is discrete, and favorite service day is categorical.\n\nYour task: (1) Define statistics, population and sample. (2) Tell the difference between a parameter and a statistic. (3) Classify three variables as categorical or quantitative.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome to Probability and Statistics. I am Dr. Alex L. Jenkins Sr. Listen, God Himself told Moses to take the sum of the congregation in Numbers 1:2, so counting people carefully is nothing new. In this course we learn how to gather numbers, read them wisely and tell the truth with them.\n\nNow watch this. Statistics is the science of collecting, organizing, analyzing and interpreting data so that we can make wise decisions. The population is the whole group we want to know about. A sample is the smaller part we actually measure. A number that describes a population is a parameter. A number that describes a sample is a statistic.\n\nLook at the two types of variables. A categorical variable puts people into groups, like favorite hymn or grade level. A quantitative variable is a real number you can count or measure, like height, age or the number of songs a choir sings. A zip code looks like a number, but it is only a label, so it is categorical.\n\nHere is an example. A pastor surveys 50 members of a church of 400. The population is the 400 members. The sample is the 50. Age is continuous. The number of children is discrete. Favorite service day is categorical.\n\nYour task is to define statistics, population and sample, tell a parameter from a statistic, and classify three variables. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 What Statistics Is and Types of Data$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Sampling and Collecting Data Honestly$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "Because it is usually impossible to ask everyone, statisticians study samples. A good sample represents the population. A bad sample leads to false conclusions. Proverbs 18:13 warns, He that answereth a matter before he heareth it, it is folly and shame unto him, and Proverbs 18:17 adds, He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him. A fair study listens to all sides.\n\nA simple random sample gives every individual an equal chance of being chosen, like drawing names from a hat. A systematic sample picks every kth individual from a list. A stratified sample divides the population into groups, such as grade levels, and takes a random sample from each group. A cluster sample randomly chooses whole groups, such as entire classrooms, and surveys everyone in them. A convenience sample uses whoever is easy to reach, and it is often biased.\n\nBias is a systematic error that favors some outcomes. Selection bias happens when some people are more likely to be chosen, such as asking only the choir about the best music. A voluntary response sample, where people choose to respond, usually attracts those with strong opinions. Undercoverage happens when part of the population is left out. Wording bias happens when a question leads the answer. Compare: Do you support the wonderful new youth center? and What is your opinion of the proposed youth center? The first question pushes people toward yes.\n\nThere are three main ways to gather data. In a sample survey we ask questions of a sample. In an observational study we watch and record without changing anything. In an experiment we apply a treatment to see its effect. In a well designed experiment, subjects are randomly assigned to groups, and there is a control group that does not receive the treatment. Only experiments can show cause and effect.\n\nYour task: (1) Name four sampling methods. (2) Explain three kinds of bias. (3) Rewrite a leading survey question so it is fair.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Proverbs 18:13 says, He that answereth a matter before he heareth it, it is folly and shame unto him. That is a rule for good statistics too. Hear everyone before you decide.\n\nNow watch this. A simple random sample gives everyone an equal chance of being chosen, like names drawn from a hat. A systematic sample takes every kth person on a list. A stratified sample splits the population into groups, like grade levels, and samples from each group. A cluster sample chooses whole groups, like entire classrooms. A convenience sample uses whoever is easy to reach, and it is often biased.\n\nLook at bias. Selection bias means some people are more likely to be chosen. A voluntary response sample draws people with strong opinions. Undercoverage leaves part of the population out. Wording bias happens when the question leads the answer. Do you support the wonderful new youth center is a leading question. What is your opinion of the proposed youth center is fair.\n\nThere are three ways to gather data. A survey asks questions. An observational study watches without changing anything. An experiment applies a treatment, with random assignment and a control group. Only a well designed experiment can show cause and effect.\n\nYour task is to name four sampling methods, explain three kinds of bias and rewrite a leading question. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Sampling and Collecting Data Honestly$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Displaying Data: Tables and Graphs$j$, $j${"readings": [{"title": "Psalm 90 (King James Version)", "url": "/portal/bible/Psalms/90"}], "body": "Raw numbers are hard to read until we organize them. Psalm 90:12 prays, So teach us to number our days, that we may apply our hearts unto wisdom. Good graphs help us number our days well by showing patterns we could not see in a list.\n\nA frequency table lists each value or category and how many times it occurs. The relative frequency is the frequency divided by the total, often written as a percent. For example, if 40 students are asked their favorite season and 10 say summer, the frequency is 10 and the relative frequency is 10 divided by 40, which is 0.25 or 25 percent.\n\nFor categorical data, we use a bar graph, where the height of each bar shows the count in a category, and the bars do not touch. A pie chart shows parts of a whole, and the percents add to 100. For quantitative data, a dot plot places a dot above each value on a number line. A stem and leaf plot splits each number into a stem and a leaf; for example, the scores 72, 75, 78 and 81 are shown as 7 with leaves 2, 5 and 8, and 8 with leaf 1. A histogram groups quantitative data into equal width intervals called bins, and the bars touch because the data are continuous.\n\nWhen you describe a graph of quantitative data, talk about its shape, center and spread, and any unusual features. A distribution is symmetric if the left and right sides are mirror images. It is skewed right if the tail stretches toward the larger values, and skewed left if the tail stretches toward the smaller values. A peak is a mode, and a distribution with two peaks is bimodal. Gaps and outliers deserve attention.\n\nExample: quiz scores of 5, 6, 6, 7, 7, 7, 8, 8, 9 make a dot plot with the tallest stack at 7 and a nearly symmetric shape.\n\nYour task: (1) Find the relative frequency of a category. (2) Choose a bar graph or a histogram for given data and explain why. (3) Describe the shape of a distribution using the words symmetric, skewed, mode and outlier.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Psalm 90:12 says, So teach us to number our days, that we may apply our hearts unto wisdom. A good graph helps us see patterns that a list of numbers hides.\n\nNow watch this. A frequency table lists each value and how many times it occurs. The relative frequency is the frequency divided by the total. If 10 of 40 students pick summer, the relative frequency is 0.25, or 25 percent.\n\nLook at the graphs. For categories, use a bar graph with bars that do not touch, or a pie chart whose parts add to 100 percent. For numbers, use a dot plot, a stem and leaf plot or a histogram. A histogram groups data into equal width bins, and its bars touch because the data are continuous.\n\nWhen you describe a graph, talk about shape, center and spread. A distribution is symmetric when the two sides are mirror images. It is skewed right when the tail stretches toward larger values, and skewed left when the tail stretches toward smaller values. A peak is a mode. Two peaks make it bimodal. Always look for gaps and outliers.\n\nExample. Scores of 5, 6, 6, 7, 7, 7, 8, 8, 9 stack tallest at 7 and look nearly symmetric.\n\nYour task is to find a relative frequency, choose the right graph and describe a shape. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Displaying Data: Tables and Graphs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Measures of Center and Spread$j$, $j${"readings": [{"title": "Proverbs 11 (King James Version)", "url": "/portal/bible/Proverbs/11"}], "body": "A single number can summarize a whole data set. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. A fair summary uses a just weight, which means it does not hide the truth.\n\nThe mean is the average. Add all the values and divide by how many there are. For the data 3, 5, 6, 7 and 9, the sum is 30, and 30 divided by 5 is 6, so the mean is 6. The median is the middle value when the data are in order. If there is an even number of values, the median is the mean of the two middle values. For 3, 5, 6, 7 and 9 the median is also 6. The mode is the value that occurs most often.\n\nThe mean and the median can tell different stories. Change the 9 to 39. The data 3, 5, 6, 7 and 39 have a sum of 60, so the mean is 12, but the median is still 6. The mean is pulled toward extreme values, so we say it is not resistant. The median is resistant. For skewed data or data with outliers, the median is usually a better description of a typical value. This matters in real life. A few very high salaries can raise the mean income of a town so that it looks richer than most families really are.\n\nSpread tells how far apart the data are. The range is the maximum minus the minimum. For 3, 5, 6, 7 and 39, the range is 39 minus 3, which is 36. The range uses only two values and is easily distorted. Two data sets can have the same mean but very different spreads. Scores of 78, 80 and 82 and scores of 60, 80 and 100 both have a mean of 80, but the second set is far more spread out.\n\nYour task: (1) Find the mean, median, mode and range of a small data set. (2) Explain why the median is resistant and the mean is not. (3) Tell when the median is the better summary.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. When we summarize data, we must use a just weight.\n\nNow watch this. The mean is the average. Add the values and divide by how many there are. For 3, 5, 6, 7 and 9, the sum is 30, and 30 divided by 5 is 6. The median is the middle value in order, also 6. The mode is the value that occurs most often.\n\nLook at what happens with an extreme value. Change the 9 to 39. Now the sum is 60, so the mean is 12, but the median is still 6. The mean is pulled toward extremes. The median is resistant. For skewed data or data with outliers, the median usually describes a typical value better. A few huge salaries can make a town look richer than most families are.\n\nSpread tells how far apart the data are. The range is the maximum minus the minimum. For 3, 5, 6, 7 and 39 the range is 36. Scores of 78, 80 and 82 and scores of 60, 80 and 100 both have a mean of 80, but the second set is far more spread out.\n\nYour task is to find the mean, median, mode and range, explain resistance and tell when the median is better. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Measures of Center and Spread$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Data and How We Describe It$j$, $j${"prompt": "Write a report of at least 250 words on describing data. Use complete sentences, show your work and label each part. Psalm 90:12 says, So teach us to number our days, that we may apply our hearts unto wisdom.\n\nPart 1: Define population, sample, parameter and statistic, and give one example of each from a church or school.\nPart 2: Name two sampling methods and two kinds of bias. Rewrite one leading survey question so that it is fair.\nPart 3: Make a frequency table, relative frequencies and either a dot plot or a histogram for ten numbers you collect, such as the number of minutes ten family members read Scripture in a week. Describe the shape.\nPart 4: Find the mean, median, mode and range of your ten numbers. Add one extreme value and show what happens to the mean and the median.\nPart 5: Explain, using Proverbs 11:1, why honest summaries matter.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 25 points. Part 4: 25 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Data and How We Describe It$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Counting with Care$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells about a time a survey, poll or count affected a decision at home, school or church, (2) explains how a poor sample or a leading question could give a false picture, (3) describes a question you would like to answer with data and how you would collect a fair sample, and (4) connects your answer to Proverbs 18:13 or Numbers 1:2. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why should a leader want honest numbers even when they are not what he hoped to see? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Counting with Care$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: What Statistics Is and Types of Data$j$, $j${"questions": [{"q": "The entire group a study wants to know about is the:", "options": ["Variable", "Population", "Sample", "Statistic"]}, {"q": "A number that describes a sample is called a:", "options": ["Population", "Category", "Statistic", "Parameter"]}, {"q": "Which variable is categorical?", "options": ["Number of siblings", "Time in seconds", "Height in inches", "Favorite hymn"]}, {"q": "The number of children in a family is what kind of variable?", "options": ["Categorical", "Continuous quantitative", "A parameter", "Discrete quantitative"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: What Statistics Is and Types of Data$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,3}'::int[], array[$j$The population is the whole group of interest.$j$,$j$A statistic describes a sample; a parameter describes a population.$j$,$j$Favorite hymn places people in groups.$j$,$j$It is counted in whole numbers, so it is discrete.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: What Statistics Is and Types of Data$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Sampling and Collecting Data Honestly$j$, $j${"questions": [{"q": "A sample in which every individual has an equal chance of being chosen is a:", "options": ["Simple random sample", "Convenience sample", "Voluntary response sample", "Biased sample"]}, {"q": "Asking only the choir which music the whole church prefers is an example of:", "options": ["A control group", "Selection bias", "A random sample", "A cluster sample"]}, {"q": "Which type of study can show cause and effect?", "options": ["A convenience survey", "A well designed experiment", "A voluntary response poll", "An observational study"]}, {"q": "Dividing students by grade level and sampling randomly from each grade is:", "options": ["A cluster sample", "A systematic sample", "A convenience sample", "A stratified sample"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Sampling and Collecting Data Honestly$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3}'::int[], array[$j$Equal chance defines a simple random sample.$j$,$j$The choir does not represent the whole church.$j$,$j$Random assignment and a control group allow cause and effect conclusions.$j$,$j$Stratified sampling samples from each group.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Sampling and Collecting Data Honestly$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Displaying Data: Tables and Graphs$j$, $j${"questions": [{"q": "Twelve of 48 students chose basketball. The relative frequency is:", "options": ["12 percent", "48 percent", "25 percent", "4 percent"]}, {"q": "Which graph is best for the favorite hymn of each member of a choir?", "options": ["A stem and leaf plot", "A bar graph", "A scatter plot", "A histogram"]}, {"q": "A distribution with a long tail toward the larger values is:", "options": ["Symmetric", "Skewed left", "Skewed right", "Bimodal"]}, {"q": "In a histogram, the bars touch because the data are:", "options": ["Categorical", "Continuous quantitative", "Labels", "Discrete categories"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Displaying Data: Tables and Graphs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,2,1}'::int[], array[$j$12 divided by 48 equals 0.25, or 25 percent.$j$,$j$Favorite hymn is categorical, so use a bar graph.$j$,$j$The tail side names the skew.$j$,$j$Bins cover an unbroken range of values.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Displaying Data: Tables and Graphs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Measures of Center and Spread$j$, $j${"questions": [{"q": "The mean of 4, 6, 8 and 10 is:", "options": ["28", "8", "6", "7"]}, {"q": "Which measure is resistant to outliers?", "options": ["The range", "The mean", "The sum", "The median"]}, {"q": "The range of 3, 5, 6, 7 and 39 is:", "options": ["36", "6", "12", "39"]}, {"q": "A town has a few extremely high incomes. Which summary best shows a typical family?", "options": ["The mean", "The maximum", "The median", "The range"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Measures of Center and Spread$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,2}'::int[], array[$j$The sum is 28, and 28 divided by 4 is 7.$j$,$j$The median is not pulled by extreme values.$j$,$j$39 minus 3 equals 36.$j$,$j$The median is not distorted by a few very high values.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Measures of Center and Spread$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Data and How We Describe It$j$, $j${"questions": [{"q": "A pastor surveys 60 of 500 members. The 500 members are the:", "options": ["Statistic", "Variable", "Population", "Sample"]}, {"q": "Zip codes are what type of variable?", "options": ["Continuous", "A parameter", "Categorical", "Discrete quantitative"]}, {"q": "A survey that only counts people who choose to call in is a:", "options": ["Stratified sample", "Cluster sample", "Voluntary response sample", "Simple random sample"]}, {"q": "A control group in an experiment:", "options": ["Is never measured", "Chooses its own treatment", "Receives the treatment twice", "Does not receive the treatment"]}, {"q": "Fifteen of 60 students chose pizza. The relative frequency is:", "options": ["60 percent", "15 percent", "25 percent", "4 percent"]}, {"q": "The mean of 2, 4, 6, 8 and 10 is:", "options": ["5", "8", "30", "6"]}, {"q": "For 3, 5, 6, 7 and 39 the median is:", "options": ["36", "12", "39", "6"]}, {"q": "A distribution with its tail stretching toward smaller values is:", "options": ["Skewed right", "Uniform", "Symmetric", "Skewed left"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Data and How We Describe It$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,3,2,3,3,3}'::int[], array[$j$The whole group is the population.$j$,$j$A zip code is only a label.$j$,$j$Self selected responses are usually biased.$j$,$j$The control group provides a comparison.$j$,$j$15 divided by 60 equals 0.25.$j$,$j$The sum is 30, and 30 divided by 5 is 6.$j$,$j$The middle value is 6.$j$,$j$The tail side names the skew.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Data and How We Describe It$j$ on conflict (item_id) do nothing;
